#pragma once
static constexpr const char* gui_page = R"ARCH00HTML(<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Arch00 Tool</title>
<style>
:root{color-scheme:dark;font-family:system-ui,sans-serif;background:#111927;color:#e5ecf5}body{margin:0;padding:2rem}main{max-width:900px;margin:auto}h1{margin-bottom:.2rem}p,.hint{color:#b4c2d3}section{background:#1c293b;padding:1.3rem;border:1px solid #36465a;border-radius:12px;margin:1rem 0}label{display:block;margin:.8rem 0 .3rem;font-weight:600}input,select,button{box-sizing:border-box;font:inherit;padding:.6rem;border-radius:6px;border:1px solid #506078}input:not([type=checkbox]){width:100%;background:#0e1926;color:#fff}select{background:#0e1926;color:#fff}button{background:#69b8f2;color:#102033;font-weight:700;cursor:pointer;margin:.5rem .3rem .2rem 0}button:disabled{opacity:.5}pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:26rem;overflow:auto;background:#0e1926;padding:1rem;border-radius:6px} .warn{border-left:4px solid #e3a946;padding-left:1rem}
</style></head><body><main><h1>Arch00 Tool</h1><p>Experimental local interface · LTAR v3</p><p class="warn">Use trusted archives and a new private output directory. No overwrite is intended, but extraction can leave partial files. Keep backups.</p>
<section><label for="archive">Archive or input directory path</label><input id="archive" placeholder="/path/to/archive.Arch00" autocomplete="off"><label for="output">Output path (extract directory or new archive for repack)</label><input id="output" placeholder="/path/to/output" autocomplete="off"><label for="replace">Replacement directory (optional, repack only)</label><input id="replace" placeholder="/path/to/mod" autocomplete="off"><label for="pattern">Pattern (optional; single-archive extract only)</label><input id="pattern" placeholder="*.dds" autocomplete="off"><p><label><input type="checkbox" id="skip"> Skip existing destinations (extract all)</label></p><label for="mode">Compression mode (test / extract)</label><select id="mode"><option value="auto">Auto</option><option value="raw">Raw stored bytes</option></select><label for="jobs">Workers (test / extract, 1–64)</label><input id="jobs" type="number" min="1" max="64" value="1"><p class="hint">Paths refer to this computer. For batch operations, enter an input directory as the archive path. Repacking stores replacements uncompressed. A successful test does not guarantee game compatibility.</p><div><button data-action="list">List</button><button data-action="test">Test</button><button data-action="extract">Extract</button><button data-action="repack">Repack</button><button data-action="test-all">Test all</button><button data-action="extract-all">Extract all</button></div></section><section><strong id="status" role="status" aria-live="polite">Ready</strong><pre id="result">Results will appear here.</pre></section></main>
<script>
'use strict';
const fragment=location.hash.slice(1); if(fragment){sessionStorage.setItem('arch00-token',fragment);history.replaceState(null,'',location.pathname)}
const token=sessionStorage.getItem('arch00-token')||'';
const buttons=document.querySelectorAll('button[data-action]');
for(const button of buttons)button.addEventListener('click',async()=>{
 const action=button.dataset.action, status=document.getElementById('status'), result=document.getElementById('result');
 if(!token){status.textContent='Missing session token. Open the URL printed by the program.';return}
 if((action==='extract'||action==='extract-all'||action==='repack')&&!confirm('Write output to the specified path? Existing files are not meant to be overwritten.'))return;
 const data={action,archive:document.getElementById('archive').value,output:document.getElementById('output').value,replace:document.getElementById('replace').value,pattern:document.getElementById('pattern').value,skip_existing:document.getElementById('skip').checked,compression:document.getElementById('mode').value,jobs:Number(document.getElementById('jobs').value)};
 buttons.forEach(b=>b.disabled=true);status.textContent='Working…';result.textContent='Please wait; large archives may take time.';
 try{const response=await fetch('/api',{method:'POST',headers:{'Content-Type':'application/json','X-Arch00-Token':token},body:JSON.stringify(data)});const body=await response.json();status.textContent=response.ok?'Done':'Error';result.textContent=body.message||'No result';}catch(err){status.textContent='Error';result.textContent=String(err)}finally{buttons.forEach(b=>b.disabled=false)}
});
</script></body></html>)ARCH00HTML";
